test_that("old names still work, warn, and map their arguments", {
  expect_warning(v <- preprocess_data(nedap, "nedap", quiet = TRUE), "prep_visits")
  expect_equal(nrow(v), nrow(nedap))
  expect_warning(a <- adg_get(v, my_break = c(40, 110), quiet = TRUE), "calc_adg")
  expect_s3_class(a, "ppt_adg")
  expect_equal(a$settings$stage_range, c(40, 110))
  expect_warning(f <- adfi_get(v, a, quiet = TRUE), "calc_adfi")
  expect_warning(r <- fcr_get(a, f, quiet = TRUE), "calc_fcr")
  expect_s3_class(r, "ppt_fcr")
  w <- testthat::capture_warnings(clean_weight_get(v, c(30, 120), w_threshold = 0.4, quiet = TRUE))
  expect_true(any(grepl("clean_weight", w)))
  expect_true(any(grepl("w_threshold", w)))
  dir <- withr::local_tempdir()
  expect_warning(adg_plot(a, save_path = dir, device = "pdf", quiet = TRUE), "plot_adg")
  expect_length(list.files(dir, pattern = "pdf$"), 2L)
})
